import org.objectweb.asm.*;import org.objectweb.asm.tree.*;import org.objectweb.asm.tree.analysis.*;import java.util.*;import java.util.zip.*;import java.nio.file.*;
public class Patch implements Opcodes{
 static final String P="dev/zomboid/remains/hygiene/";static int hooks;
 static byte[] patch(byte[] b){ClassNode c=new ClassNode();new ClassReader(b).accept(c,0);if(!c.name.equals("dev/zomboid/remains/ZombieRemainsLoot"))return b;for(MethodNode m:c.methods){if(m.name.equals("<init>")){for(AbstractInsnNode n:m.instructions.toArray())if(n.getOpcode()==RETURN){InsnList x=new InsnList();x.add(new VarInsnNode(ALOAD,1));x.add(new TypeInsnNode(NEW,P+"HygieneRegistry"));x.add(new InsnNode(DUP));x.add(new MethodInsnNode(INVOKESPECIAL,P+"HygieneRegistry","<init>","()V",false));x.add(new MethodInsnNode(INVOKEINTERFACE,"net/neoforged/bus/api/IEventBus","addListener","(Ljava/util/function/Consumer;)V",true));m.instructions.insertBefore(n,x);hooks++;}}if(m.name.equals("cleanup")){InsnList x=new InsnList();x.add(new VarInsnNode(ALOAD,0));x.add(new MethodInsnNode(INVOKESTATIC,P+"Hygiene","server","(Ljava/lang/Object;)V",false));m.instructions.insert(x);hooks++;}}ClassWriter w=new ClassWriter(ClassWriter.COMPUTE_MAXS);c.accept(w);return w.toByteArray();}
 static byte[] listener(){String name=P+"HygieneRegistry",event="net/neoforged/neoforge/registries/RegisterEvent";ClassWriter w=new ClassWriter(0);w.visit(V21,ACC_PUBLIC|ACC_FINAL,name,"Ljava/lang/Object;Ljava/util/function/Consumer<L"+event+";>;","java/lang/Object",new String[]{"java/util/function/Consumer"});MethodVisitor m=w.visitMethod(ACC_PUBLIC,"<init>","()V",null,null);m.visitCode();m.visitVarInsn(ALOAD,0);m.visitMethodInsn(INVOKESPECIAL,"java/lang/Object","<init>","()V",false);m.visitInsn(RETURN);m.visitMaxs(1,1);m.visitEnd();m=w.visitMethod(ACC_PUBLIC,"accept","(L"+event+";)V",null,null);m.visitCode();m.visitVarInsn(ALOAD,1);m.visitMethodInsn(INVOKESTATIC,P+"HygieneContent","register","(Ljava/lang/Object;)V",false);m.visitInsn(RETURN);m.visitMaxs(1,2);m.visitEnd();m=w.visitMethod(ACC_PUBLIC|ACC_BRIDGE|ACC_SYNTHETIC,"accept","(Ljava/lang/Object;)V",null,null);m.visitCode();m.visitVarInsn(ALOAD,0);m.visitVarInsn(ALOAD,1);m.visitTypeInsn(CHECKCAST,event);m.visitMethodInsn(INVOKEVIRTUAL,name,"accept","(L"+event+";)V",false);m.visitInsn(RETURN);m.visitMaxs(2,2);m.visitEnd();w.visitEnd();return w.toByteArray();}
 static void verify(byte[]b)throws Exception{ClassNode c=new ClassNode();new ClassReader(b).accept(c,0);for(MethodNode m:c.methods)if((m.access&(ACC_ABSTRACT|ACC_NATIVE))==0)new Analyzer<BasicValue>(new BasicVerifier()).analyze(c.name,m);}
 public static void main(String[]a)throws Exception{Map<String,byte[]> entries=new TreeMap<>();try(ZipFile z=new ZipFile(a[0])){for(ZipEntry e:Collections.list(z.entries())){byte[]b=z.getInputStream(e).readAllBytes();entries.put(e.getName(),e.getName().endsWith(".class")?patch(b):b);}}if(hooks!=2)throw new IllegalStateException("hooks "+hooks);try(var files=Files.walk(Path.of(a[2]))){for(Path p:files.filter(p->p.toString().endsWith(".class")).toList())entries.put(Path.of(a[2]).relativize(p).toString(),Files.readAllBytes(p));}entries.put(P+"HygieneRegistry.class",listener());try(ZipOutputStream z=new ZipOutputStream(Files.newOutputStream(Path.of(a[1])))){for(var e:entries.entrySet()){if(e.getKey().startsWith(P)&&e.getKey().endsWith(".class")||e.getKey().equals("dev/zomboid/remains/ZombieRemainsLoot.class"))verify(e.getValue());ZipEntry n=new ZipEntry(e.getKey());n.setTime(0);z.putNextEntry(n);z.write(e.getValue());z.closeEntry();}}System.out.println("Two native hygiene registration/server hooks verified");}
}
